practice.solutionCode:
sealed interface Result { data class Success(val value: String) : Result; data class Failure(val error: String) : Result }
fun render(result: Result) = when (result) { is Result.Success -> result.value; is Result.Failure -> result.error }
fun main() = println(render(Result.Success("완료")))

